-      const msgHdr =
-        MailServices.messageServiceFromURI(uri).messageURIToMsgHdr(uri);
-      let index = gDBView.findIndexOfMsgHdr(msgHdr, expand);
-      // While the first message in a collapsed group returns the index of the
