-      try {
-        const thread = gDBView.getThreadContainingMsgHdr(msgHdr);
-        const rootMsgHdr = thread.getRootHdr();
-        index = gDBView.findIndexOfMsgHdr(rootMsgHdr, false);
-        if (index != nsMsgViewIndex_None) {
-          indices.add(index);
-          if (uri == currentUri) {
